#!/usr/bin/env python3
"""
Self-contained exact verification suite for the five-qubit logical Bell paper.
Only the Python standard library is required.
"""
from __future__ import annotations
import time

STATIC_SUITE = '#!/usr/bin/env python3\n"""Independent exact reconstruction of the static five-qubit phase theorem."""\nfrom itertools import product, combinations\nfrom fractions import Fraction as F\nfrom collections import defaultdict, Counter\nfrom math import comb\n\nSTABS=("XZZXI","IXZZX","XIXZZ","ZXIXZ")\nACTIONS=tuple((b,s) for b in "XYZ" for s in (0,1))\n\n# Compatible physical Bell-parity assignments.\nVALID=[]\nfor bits in product((0,1), repeat=10):\n    x=bits[:5]; z=bits[5:]\n    if (x[0]^z[1]^z[2]^x[3],\n        x[1]^z[2]^z[3]^x[4],\n        x[0]^x[2]^z[3]^z[4],\n        z[0]^x[1]^x[3]^z[4]) == (0,0,0,0):\n        VALID.append((bits,sum(x)&1,sum(z)&1))\nassert len(VALID)==64\n\ndef parity(bits,P,i):\n    x,z=bits[i],bits[5+i]\n    return x if P=="X" else z if P=="Z" else 1^x^z\n\ndef observation(bits,branch):\n    out=[]\n    for i,b in enumerate(branch):\n        if b is None: continue\n        P,status=b\n        out.append(parity(bits,P,i))\n        if status=="S":\n            out.extend((bits[i],bits[5+i]))\n    return tuple(out)\n\ndef identifiable(branch):\n    cells=defaultdict(set)\n    for bits,lx,lz in VALID:\n        cells[observation(bits,branch)].add((lx,lz))\n    return all(len(labels)==1 for labels in cells.values())\n\n# Precompute logical identifiability for all 7^5 branch geometries once.\nBRANCH_STATES=(None,)+tuple((P,s) for P in "XYZ" for s in "SF")\nIDENTIFIABLE={branch:identifiable(branch) for branch in product(BRANCH_STATES,repeat=5)}\nassert len(IDENTIFIABLE)==7**5\n\ndef sector_vector(scheme):\n    vals=[]\n    for k in range(6):\n        good=tot=0\n        for surviving in combinations(range(5),k):\n            S=set(surviving)\n            for bits,_,_ in VALID:\n                branch=[]\n                for i,(P,resolved_half) in enumerate(scheme):\n                    if i not in S:\n                        branch.append(None)\n                    else:\n                        status="S" if parity(bits,P,i)==resolved_half else "F"\n                        branch.append((P,status))\n                good += IDENTIFIABLE[tuple(branch)]\n                tot += 1\n        vals.append(F(good,tot))\n    return tuple(vals)\n\ndef poly_coeffs(s):\n    coeff=[F(0) for _ in range(6)]\n    for k in range(6):\n        for j in range(6-k):\n            coeff[k+j]+=s[k]*comb(5,k)*comb(5-k,j)*((-1)**j)\n    return tuple(coeff)\n\n# Five-qubit normalizer check.\ndef pv5(word):\n    x=z=0\n    for i,p in enumerate(word):\n        if p in "XY": x|=1<<i\n        if p in "ZY": z|=1<<i\n    return x|(z<<5)\n\ndef symp(a,b):\n    ax=a&31; az=(a>>5)&31; bx=b&31; bz=(b>>5)&31\n    return ((ax&bz).bit_count()+(az&bx).bit_count())&1\n\ndef rank(rows):\n    piv={}\n    for v in rows:\n        x=v\n        while x:\n            c=x.bit_length()-1\n            if c in piv: x^=piv[c]\n            else: piv[c]=x; break\n    return len(piv)\n\ndef in_span(v,rows): return rank(list(rows)+[v])==rank(rows)\n\nS5=[pv5(g) for g in STABS]\nlogical_words=[]\nfor word in map("".join,product("XYZ",repeat=5)):\n    v=pv5(word)\n    if all(symp(v,g)==0 for g in S5) and not in_span(v,S5):\n        logical_words.append(word)\nlogical_words=sorted(logical_words)\nassert len(logical_words)==18\n\ncounts=Counter()\nbasis_classes=defaultdict(set)\nfor scheme in product(ACTIONS,repeat=5):\n    s=sector_vector(scheme)\n    counts[s]+=1\n    basis_classes["".join(p for p,_ in scheme)].add(s)\n\nH=(F(0),F(0),F(0),F(1,8),F(9,16),F(31,32))\nG=(F(0),F(0),F(0),F(1,8),F(47,80),F(7,8))\nC=(F(0),F(0),F(0),F(1,8),F(23,40),F(13,16))\nL=(F(0),F(0),F(0),F(1,8),F(13,20),F(3,4))\nassert counts==Counter({H:576,G:5760,C:720,L:720})\n\n# High class = full-support nontrivial logical Pauli normalizer words.\nhigh_bases=sorted(b for b,classes in basis_classes.items() if classes=={H})\nassert high_bases==logical_words\n\nPH=poly_coeffs(H); PL=poly_coeffs(L)\n# PH - PL = (7/32) q^4 (3q-2)\ndiff=tuple(PH[i]-PL[i] for i in range(6))\nassert diff==(F(0),F(0),F(0),F(0),F(-7,16),F(21,32))\n\ndef peval(c,q):\n    out=F(0)\n    for a in reversed(c): out=out*q+a\n    return out\n\nqc=F(2,3)\nassert peval(PH,qc)==peval(PL,qc)==F(86,243)\nassert peval(PH,F(1))==F(31,32)\nassert peval(PL,F(1))==F(3,4)\n\nprint("PASS: exact static phase theorem")\nprint("compatible_assignments=64")\nprint("static_schemes=7776")\nprint("class_multiplicities=576,5760,720,720")\nprint("high_survival_normalizer_words=18")\nprint("q_c=2/3")\nprint("P_static(q_c)=86/243")\n'
ADAPTIVE_SUITE = '#!/usr/bin/env python3\n"""Independent exact Bellman reconstruction of the adaptive five-qubit theorem."""\nfrom itertools import product\nfrom fractions import Fraction as F\nfrom collections import Counter\n\n# ---------------- compatible Bell assignments ----------------\nVALID=[]\nfor bits in product((0,1), repeat=10):\n    x=bits[:5]; z=bits[5:]\n    if (x[0]^z[1]^z[2]^x[3],\n        x[1]^z[2]^z[3]^x[4],\n        x[0]^x[2]^z[3]^z[4],\n        z[0]^x[1]^x[3]^z[4]) == (0,0,0,0):\n        VALID.append((bits,sum(x)&1,sum(z)&1))\nassert len(VALID)==64\n\nALL=(1<<64)-1\nLOGIC={}\nfor lx in (0,1):\n    for lz in (0,1):\n        m=0\n        for j,(_,a,b) in enumerate(VALID):\n            if (a,b)==(lx,lz): m|=1<<j\n        LOGIC[lx,lz]=m\n\ndef solved(omega):\n    return sum(bool(omega&m) for m in LOGIC.values())<=1\n\ndef parity(bits,P,i):\n    x,z=bits[i],bits[5+i]\n    return x if P=="X" else z if P=="Z" else 1^x^z\n\n# For an intact physical BM, failure gives one parity branch.\n# The resolved half gives full physical Bell information, hence separate (x,z) branches.\nACTION_MASKS={}\nfor i in range(5):\n    for P in "XYZ":\n        for r in (0,1):\n            failure=0; success={}\n            for j,(bits,_,_) in enumerate(VALID):\n                if parity(bits,P,i)!=r:\n                    failure|=1<<j\n                else:\n                    key=(bits[i],bits[5+i])\n                    success[key]=success.get(key,0)|(1<<j)\n            ACTION_MASKS[i,P,r]=(failure,tuple(success.values()))\n\ndef branches(U,omega,action):\n    i,P,r=action\n    U2=U&~(1<<i)\n    den=omega.bit_count()\n    fail,succ=ACTION_MASKS[action]\n    intact=[]\n    f=omega&fail\n    if f: intact.append((F(f.bit_count(),den),(U2,f)))\n    for m in succ:\n        s=omega&m\n        if s: intact.append((F(s.bit_count(),den),(U2,s)))\n    return (U2,omega),intact\n\n# ---------------- build complete reachable graph ----------------\nROOT=(31,ALL)\nstates=set(); nonterminal=[]\nstack=[ROOT]\nwhile stack:\n    state=stack.pop()\n    if state in states: continue\n    states.add(state)\n    U,omega=state\n    if solved(omega) or U==0: continue\n    nonterminal.append(state)\n    for i in range(5):\n        if not ((U>>i)&1): continue\n        for P in "XYZ":\n            for r in (0,1):\n                erasure,intact=branches(U,omega,(i,P,r))\n                stack.append(erasure)\n                stack.extend(ch for _,ch in intact)\n\nassert len(states)==49312\nassert len(nonterminal)==36941\nACTIONS={\n    state:[(i,P,r) for i in range(5) if (state[0]>>i)&1 for P in "XYZ" for r in (0,1)]\n    for state in nonterminal\n}\nassert sum(len(v) for v in ACTIONS.values())==313200\n\n# Bottom-up order because each action removes one physical pair.\nORDER=sorted(states,key=lambda s:s[0].bit_count())\n\ndef solve_at(q):\n    V={}\n    for state in ORDER:\n        U,omega=state\n        if solved(omega):\n            V[state]=F(1); continue\n        if U==0:\n            V[state]=F(0); continue\n        best=F(-1)\n        for action in ACTIONS[state]:\n            erasure,intact=branches(U,omega,action)\n            val=(1-q)*V[erasure]\n            val+=q*sum((p*V[ch] for p,ch in intact),F(0))\n            if val>best: best=val\n        V[state]=best\n    return V\n\n# Six exact samples are sufficient to interpolate degree <= 5 values.\nSAMPLE_Q=(F(0),F(1,5),F(2,5),F(3,5),F(4,5),F(1))\nVALUES=[solve_at(q) for q in SAMPLE_Q]\n\n# ---------------- exact polynomial arithmetic ----------------\ndef trim(p):\n    p=list(p)\n    while len(p)>1 and p[-1]==0: p.pop()\n    return tuple(p)\ndef add(a,b):\n    n=max(len(a),len(b))\n    return trim([(a[i] if i<len(a) else F(0))+(b[i] if i<len(b) else F(0)) for i in range(n)])\ndef sub(a,b):\n    n=max(len(a),len(b))\n    return trim([(a[i] if i<len(a) else F(0))-(b[i] if i<len(b) else F(0)) for i in range(n)])\ndef scale(a,c): return trim([c*x for x in a])\ndef mul(a,b):\n    out=[F(0)]*(len(a)+len(b)-1)\n    for i,x in enumerate(a):\n        for j,y in enumerate(b): out[i+j]+=x*y\n    return trim(out)\ndef qmul(a): return (F(0),)+tuple(a)\n# Precompute the six Lagrange basis polynomials once.  Interpolating every\n# state is then only a 6x6 rational matrix-vector multiply.\nLAGRANGE=[]\nfor i,xi in enumerate(SAMPLE_Q):\n    num=(F(1),); den=F(1)\n    for j,xj in enumerate(SAMPLE_Q):\n        if i==j: continue\n        num=mul(num,(-xj,F(1)))\n        den*=xi-xj\n    LAGRANGE.append(scale(num,F(1,1)/den))\n\ndef interpolate_values(ys):\n    coeff=[F(0)]*6\n    for yi,basis in zip(ys,LAGRANGE):\n        if yi==0: continue\n        for k,c in enumerate(basis): coeff[k]+=yi*c\n    return trim(coeff)\n\nVpoly={state:interpolate_values([values[state] for values in VALUES]) for state in states}\n\nassert Vpoly[ROOT]==(F(0),F(0),F(0),F(5,4),F(7,4),F(-65,32))\n\n# Bellman gaps expected from the theorem.\nGAPS={\n    (F(0),):"0",\n    (F(0),F(1,2)):"q/2",\n    (F(0),F(1)):"q",\n    (F(0),F(0),F(1,4)):"q^2/4",\n    (F(0),F(0),F(1,2)):"q^2/2",\n    (F(0),F(1,2),F(-1,2)):"q(1-q)/2",\n    (F(0),F(1),F(-1)):"q(1-q)",\n    (F(0),F(0),F(0),F(1,8)):"q^3/8",\n    (F(0),F(0),F(0),F(1,4)):"q^3/4",\n    (F(0),F(0),F(0),F(3,8)):"3q^3/8",\n    (F(0),F(0),F(1,4),F(-1,4)):"q^2(1-q)/4",\n    (F(0),F(0),F(3,4),F(-3,4)):"3q^2(1-q)/4",\n}\nEXPECTED_COUNTS=Counter({\n    "0":241200,\n    "q/2":11520,\n    "q":2880,\n    "q^2/4":14400,\n    "q^2/2":14400,\n    "q(1-q)/2":11520,\n    "q(1-q)":5760,\n    "q^3/8":1440,\n    "q^3/4":720,\n    "3q^3/8":720,\n    "q^2(1-q)/4":2880,\n    "3q^2(1-q)/4":5760,\n})\n\ncounts=Counter()\nfor state in nonterminal:\n    U,omega=state\n    has_zero=False\n    for action in ACTIONS[state]:\n        erasure,intact=branches(U,omega,action)\n        intact_poly=(F(0),)\n        for p,ch in intact:\n            intact_poly=add(intact_poly,scale(Vpoly[ch],p))\n        # Q=(1-q)V_E + q*sum p_o V_o = V_E + q(S-V_E)\n        Q=add(Vpoly[erasure],qmul(sub(intact_poly,Vpoly[erasure])))\n        gap=trim(sub(Vpoly[state],Q))\n        assert gap in GAPS, ("unexpected Bellman gap",gap)\n        counts[GAPS[gap]]+=1\n        has_zero |= gap==(F(0),)\n    assert has_zero, "Bellman candidate has no attaining action"\n\nassert counts==EXPECTED_COUNTS\nassert sum(counts.values())==313200\n\n# Independent exact checkpoints.\nexpected_root={\n    F(0):F(0),\n    F(1,5):F(243,20000),\n    F(2,5):F(13,125),\n    F(3,5):F(6777,20000),\n    F(4,5):F(432,625),\n    F(1):F(31,32),\n}\nfor q,V in zip(SAMPLE_Q,VALUES):\n    assert V[ROOT]==expected_root[q]\n\nprint("PASS: exact adaptive Bellman theorem")\nprint("information_states=49312")\nprint("nonterminal_states=36941")\nprint("action_comparisons=313200")\nprint("distinct_gap_forms=12")\nprint("P_ad(q)=5/4 q^3 + 7/4 q^4 - 65/32 q^5")\nprint("gap_multiplicities=",dict(counts))\n'
GAUGE_SUITE = '#!/usr/bin/env python3\n"""Exact full-record gauge and 7^5 branchwise invariance test."""\nfrom itertools import product\n\nSTABS=("XZZXI","IXZZX","XIXZZ","ZXIXZ")\n\n# ---------- Pauli / symplectic utilities on ten physical qubits ----------\ndef pvec(paulis):\n    x=z=0\n    for i,p in enumerate(paulis):\n        if p in "XY": x|=1<<i\n        if p in "ZY": z|=1<<i\n    return x|(z<<10)\n\ndef rank(rows):\n    piv={}\n    for v in rows:\n        x=v\n        while x:\n            c=x.bit_length()-1\n            if c in piv: x^=piv[c]\n            else: piv[c]=x; break\n    return len(piv)\n\ndef in_span(v,rows): return rank(list(rows)+[v])==rank(rows)\n\nSBASE=[pvec(g+"IIIII") for g in STABS]+[pvec("IIIII"+g) for g in STABS]\nLX=pvec("XXXXXXXXXX"); LZ=pvec("ZZZZZZZZZZ")\nCOMP={"X":"Z","Z":"X","Y":"X"}\n\ndef prow(i,P,both=True):\n    s=["I"]*10\n    s[i]=P\n    if both: s[5+i]=P\n    return pvec("".join(s))\n\nPAIR={(i,P):prow(i,P,True) for i in range(5) for P in "XYZ"}\nSECOND={(i,P):prow(i,COMP[P],True) for i in range(5) for P in "XYZ"}\nLOCAL={(i,P):prow(i,P,False) for i in range(5) for P in "XYZ"}\n\ndef identifiable(branch,full_record):\n    rows=list(SBASE)\n    for i,b in enumerate(branch):\n        if b is None: continue\n        P,status=b\n        rows.append(PAIR[i,P])\n        if status=="S":\n            rows.append(SECOND[i,P])\n        elif full_record:\n            rows.append(LOCAL[i,P])\n    return in_span(LX,rows) and in_span(LZ,rows)\n\n# ---------- exhaustive branchwise coarse/full comparison ----------\nSTATES=(None,)+tuple((P,s) for P in "XYZ" for s in "SF")\nchanged=0\nfor branch in product(STATES,repeat=5):\n    coarse=identifiable(branch,False)\n    full=identifiable(branch,True)\n    if coarse!=full:\n        changed+=1\nassert changed==0\n\n# ---------- stabilizer gauge witnesses ----------\nWITNESS={\n    (0,"X"):"g4",(0,"Y"):"g1",(0,"Z"):"g1",\n    (1,"X"):"g1",(1,"Y"):"g2",(1,"Z"):"g2",\n    (2,"X"):"g1",(2,"Y"):"g3",(2,"Z"):"g3",\n    (3,"X"):"g2",(3,"Y"):"g1",(3,"Z"):"g1",\n    (4,"X"):"g3",(4,"Y"):"g2",(4,"Z"):"g2",\n}\nGEN=dict(zip(("g1","g2","g3","g4"),STABS))\n\ndef anticommutes_single(a,b):\n    return a!="I" and b!="I" and a!=b\n\n# Local witness flips the chosen P outcome.\nfor (i,P),gname in WITNESS.items():\n    assert anticommutes_single(GEN[gname][i],P)\n\n# On any future pair, the doubled action g_j \\otimes g_j commutes\n# with every doubled Q_j \\otimes Q_j: the one-block sign occurs twice.\nfor (i,P),gname in WITNESS.items():\n    g=GEN[gname]\n    for j in range(5):\n        if j==i: continue\n        for Q in "XYZ":\n            one_block_minus=int(anticommutes_single(g[j],Q))\n            doubled_minus=(one_block_minus+one_block_minus)&1\n            assert doubled_minus==0\n\n# Projector identity at fixed failure product s:\n# Pi_(a,b)+Pi_(-a,-b)=1/2(I+s P_A P_B).\n# It is enough to verify the four classical eigenvalue indicators.\nfor s in (-1,1):\n    for a in (-1,1):\n        b=s*a\n        for pa in (-1,1):\n            for pb in (-1,1):\n                lhs=int((pa,pb)==(a,b))+int((pa,pb)==(-a,-b))\n                rhs=(1+s*pa*pb)//2\n                assert lhs==rhs\n\nprint("PASS: full failure-record gauge equivalence")\nprint("branch_geometries_checked=16807")\nprint("branches_with_changed_identifiability=0")\nprint("gauge_witnesses_checked=15")\nprint("future_doubled_parity_commutators_checked=",15*4*3)\n'

def run_suite(name: str, source: str) -> None:
    print("\n" + "="*78)
    print(name)
    print("="*78)
    ns = {"__name__": "__main__", "__file__": f"<{name}>"}
    start = time.time()
    exec(compile(source, f"<{name}>", "exec"), ns, ns)
    print(f"elapsed_seconds={time.time()-start:.3f}")

def main() -> None:
    overall = time.time()
    run_suite("[1/3] STATIC PHASE THEOREM", STATIC_SUITE)
    run_suite("[2/3] ADAPTIVE BELLMAN THEOREM", ADAPTIVE_SUITE)
    run_suite("[3/3] FAILURE-RECORD GAUGE THEOREM", GAUGE_SUITE)
    print("\n" + "="*78)
    print("ALL EXACT VERIFICATION TESTS PASSED")
    print(f"total_elapsed_seconds={time.time()-overall:.3f}")
    print("="*78)

if __name__ == "__main__":
    main()
